INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES
(460001, 'The next ship is always late, and you look like someone with somewhere to be.', 'The next ship is always late, and you look like someone with somewhere to be.', 100, 0),
(460002, 'The harbor\'s a fine place to wait, if you like waiting. I don\'t.', 'The harbor\'s a fine place to wait, if you like waiting. I don\'t.', 100, 0),
(460003, 'Ships come and go on the Lady\'s schedule. Mine run on yours.', 'Ships come and go on the Lady\'s schedule. Mine run on yours.', 100, 0),
(460004, 'The sea answers to Elune, and Elune keeps her own time. For you, we may hasten it.', 'The sea answers to Elune, and Elune keeps her own time. For you, we may hasten it.', 100, 0),
(460005, 'The ferry drifts as the tide wills. If your errand cannot wait, speak.', 'The ferry drifts as the tide wills. If your errand cannot wait, speak.', 100, 0),
(460006, 'The naaru teach patience. They also teach compassion for those who have none.', 'The naaru teach patience. They also teach compassion for those who have none.', 100, 0),
(460007, 'Between here and Menethil there\'s naught but cold water and colder wind. Skip both.', 'Between here and Menethil there\'s naught but cold water and colder wind. Skip both.', 100, 0),
(460008, 'Everyone at this keep is waiting on a boat, a letter, or an order. You don\'t have to be.', 'Everyone at this keep is waiting on a boat, a letter, or an order. You don\'t have to be.', 100, 0),
(460009, 'Time is money, friend. The ferry wastes one, and I save you the other.', 'Time is money, friend. The ferry wastes one, and I save you the other.', 100, 0),
(460010, 'Boat to Booty Bay just left. Lucky for you, I never leave.', 'Boat to Booty Bay just left. Lucky for you, I never leave.', 100, 0),
(460011, 'Skip the line, skip the sky-sickness. Where to?', 'Skip the line, skip the sky-sickness. Where to?', 100, 0),
(460012, 'Zeppelins! Marvels of engineering. Slow marvels. I\'m faster.', 'Zeppelins! Marvels of engineering. Slow marvels. I\'m faster.', 100, 0),
(460013, 'The zeppelin\'s late, the crew\'s dead, and you\'ve got places to be. Talk to me.', 'The zeppelin\'s late, the crew\'s dead, and you\'ve got places to be. Talk to me.', 100, 0),
(460014, 'Every minute you stand around here, something in the jungle gets hungrier. Let\'s move.', 'Every minute you stand around here, something in the jungle gets hungrier. Let\'s move.', 100, 0),
(460015, 'Long way down, longer way around. I go direct.', 'Long way down, longer way around. I go direct.', 100, 0),
(460016, 'The war doesn\'t wait for the zeppelin schedule, and neither should you.', 'The war doesn\'t wait for the zeppelin schedule, and neither should you.', 100, 0),
(460017, 'The Dark Lady wants results yesterday. I deliver them today.', 'The Dark Lady wants results yesterday. I deliver them today.', 100, 0),
(460018, 'The turtle takes its time, and the turtle is wise. The sea has told me a shorter way.', 'The turtle takes its time, and the turtle is wise. The sea has told me a shorter way.', 100, 0),
(460019, 'The waves carry all things in their own time. Or, if you prefer, right now.', 'The waves carry all things in their own time. Or, if you prefer, right now.', 100, 0),
(460020, 'The elders say the journey itself teaches. Some journeys teach only that boats are slow.', 'The elders say the journey itself teaches. Some journeys teach only that boats are slow.', 100, 0);
