-- Instant ferry/zeppelin travel: expediter NPCs on every boat dock and zeppelin tower.
-- Analogue of InstantFlightPaths for the ship/zeppelin network; each NPC offers the
-- same destinations the dock's real transports serve, via gossip + SmartAI teleport.

-- REPLACE (not DELETE+INSERT): codestyle forbids DELETE FROM creature_template.

DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 460001 AND 460020;

DELETE FROM `creature` WHERE `guid` BETWEEN 46000001 AND 46000020;

DELETE FROM `npc_text` WHERE `ID` BETWEEN 460001 AND 460020;

DELETE FROM `gossip_menu` WHERE `MenuID` BETWEEN 460001 AND 460020;

DELETE FROM `gossip_menu_option` WHERE `MenuID` BETWEEN 460001 AND 460020;

DELETE FROM `smart_scripts` WHERE `entryorguid` BETWEEN 460001 AND 460020 AND `source_type` = 0;
